scwin.btn_button1_onclick = function (e) {
    grd_gridView1.setGridSize("359px", "140px")
};

scwin.btn_button2_onclick = function (e) {
    grd_gridView1.setGridSize("359px", "502px")
};

	scwin.checkVal = function() {
		const dataLayer = WebSquare.wUnit.getDomById('mf_grd_gridView1_dataLayer').offsetHeight;
		const innerTable = WebSquare.wUnit.getDomById('mf_grd_gridView1_body_table').offsetHeight;
		const layout = 30;		
		return dataLayer - layout < innerTable;
	}	
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "1000");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_button1').click()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_gridView1_scrollY_div').scrollTop = 280");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_button2').click()");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_gridView1_scrollY_div').scrollTop = 600");
		WebSquare.wUnit.addCommand("pause", "500");				
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_button1').click()");
		WebSquare.wUnit.addCommand("pause", "500");				
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_button2').click()");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_button1').click()");
		WebSquare.wUnit.addCommand("pause", "500");				
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_button2').click()");
		WebSquare.wUnit.addCommand("pause", "500");			
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_gridView1_scrollY_div').scrollTop = 600");
		WebSquare.wUnit.addCommand("pause", "500");				
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");	
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest()
